@using System.Threading
@inject IProductService ProductService
@implements IDisposable

<div class="product-search">
    <input type="text"
           placeholder="Search products…"
           @bind="searchText"
           @bind:event="oninput"
           @bind:after="OnSearchTextChanged" />

    @if (isLoading)
    {
        <div class="product-search-status">Searching…</div>
    }
    else if (errorMessage is not null)
    {
        <div class="product-search-error">
            <span>@errorMessage</span>
            <button @onclick="RetrySearch">Retry</button>
        </div>
    }
    else if (products is { Count: 0 } && hasSearched)
    {
        <div class="product-search-status">No products found.</div>
    }

    @if (products is { Count: > 0 })
    {
        <div class="product-search-results">
            @foreach (var product in products)
            {
                <div class="product-card" @onclick="() => OnProductSelected.InvokeAsync(product)">
                    <img src="@product.ImageUrl" alt="@product.Name" />
                    <h4>@product.Name</h4>
                    <span class="product-price">@product.Price.ToString("C")</span>
                </div>
            }
        </div>
    }
</div>

@code {
    [Parameter]
    public EventCallback<Product> OnProductSelected { get; set; }

    private string searchText = string.Empty;
    private List<Product>? products;
    private bool isLoading;
    private bool hasSearched;
    private string? errorMessage;

    private CancellationTokenSource? debounceTokenSource;
    private CancellationTokenSource? searchTokenSource;

    private async Task OnSearchTextChanged()
    {
        // Cancel any pending debounce timer and in-flight search.
        CancelDebounce();

        var query = searchText.Trim();
        if (string.IsNullOrEmpty(query))
        {
            CancelSearch();
            products = null;
            hasSearched = false;
            errorMessage = null;
            return;
        }

        debounceTokenSource = new CancellationTokenSource();
        var debounceToken = debounceTokenSource.Token;

        try
        {
            await Task.Delay(300, debounceToken);
        }
        catch (TaskCanceledException)
        {
            return; // User typed again — a newer debounce will fire.
        }

        await ExecuteSearchAsync(query);
    }

    private async Task ExecuteSearchAsync(string query)
    {
        CancelSearch();

        searchTokenSource = new CancellationTokenSource();
        var token = searchTokenSource.Token;

        isLoading = true;
        errorMessage = null;

        try
        {
            products = await ProductService.SearchAsync(query, token);
            hasSearched = true;
        }
        catch (OperationCanceledException)
        {
            return; // Superseded by a newer search.
        }
        catch (Exception)
        {
            products = null;
            errorMessage = "Something went wrong. Please try again.";
        }
        finally
        {
            if (!token.IsCancellationRequested)
            {
                isLoading = false;
            }
        }
    }

    private async Task RetrySearch()
    {
        var query = searchText.Trim();
        if (!string.IsNullOrEmpty(query))
        {
            await ExecuteSearchAsync(query);
        }
    }

    private void CancelDebounce()
    {
        debounceTokenSource?.Cancel();
        debounceTokenSource?.Dispose();
        debounceTokenSource = null;
    }

    private void CancelSearch()
    {
        searchTokenSource?.Cancel();
        searchTokenSource?.Dispose();
        searchTokenSource = null;
    }

    public void Dispose()
    {
        CancelDebounce();
        CancelSearch();
    }
}

